
import React, { Suspense } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { CheckCircle } from 'lucide-react';
import Image from 'next/image';
import { format, parseISO } from 'date-fns';
import { createSupabaseServerClient } from '@/lib/supabase/server';
import { notFound, redirect } from 'next/navigation';
import AcknowledgementActions from './AcknowledgementActions';

async function getApplicationData(id: string) {
    const supabase = createSupabaseServerClient();
    const { data: { session } } = await supabase.auth.getSession();

    if (!session) {
        redirect(`/login?redirectTo=/dashboard/acknowledgement/${id}`);
    }

    const { data, error } = await supabase
        .from('applications')
        .select('*')
        .eq('id', id)
        .eq('user_id', session.user.id) // Ensure user can only see their own
        .single();

    if (error || !data) {
        console.error('Error fetching acknowledgement data:', error);
        notFound();
    }

    return data;
}

async function AcknowledgementLetter({ id }: { id: string }) {
    const applicationData = await getApplicationData(id);

    const applicationId = applicationData.original_permit_id || applicationData.din || applicationData.id;
    const applicantName = applicationData.applicant_name;
    const submissionDate = format(parseISO(applicationData.created_at), 'MMMM d, yyyy');

    return (
         <Card className="w-full max-w-4xl mx-auto shadow-2xl print:shadow-none">
            <CardHeader className="bg-muted/30 p-8 print:bg-transparent">
                <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                    <Image src="/image/logo.png" alt="KASUPDA Logo" width={80} height={80} className="h-20 w-20" />
                    <div className="text-center sm:text-right">
                        <h1 className="text-xl font-bold text-primary">KADUNA STATE URBAN PLANNING AND DEVELOPMENT AUTHORITY</h1>
                        <p className="text-sm text-muted-foreground">No 4 Bida Road, Business District Area, Kaduna State</p>
                        <p className="text-sm text-muted-foreground">Hotline: 09037236253</p>
                    </div>
                </div>
            </CardHeader>
            <CardContent className="p-8 md:p-12 space-y-8">
                <div className="text-center">
                    <CheckCircle className="h-16 w-16 text-green-500 mx-auto mb-4" />
                    <CardTitle className="text-2xl font-bold">Application Acknowledgement</CardTitle>
                    <CardDescription className="text-muted-foreground">Your application has been successfully submitted.</CardDescription>
                </div>
                
                <div className="space-y-4 text-sm sm:text-base">
                    <p><strong>Date:</strong> {submissionDate}</p>
                    <p><strong>Applicant Name:</strong> {applicantName || 'N/A'}</p>
                    <p><strong>Application ID:</strong> <span className="font-mono bg-muted px-2 py-1 rounded">{applicationId || 'N/A'}</span></p>
                </div>
                
                <div className="prose prose-sm max-w-none text-foreground">
                    <p>
                        Dear {applicantName || 'Applicant'},
                    </p>
                    <p>
                        This letter is to confirm that we have successfully received your application for a <strong>{applicationData.type}</strong>. The details provided have been logged into our system for processing.
                    </p>
                    <p>
                        Your Application ID is <strong>{applicationId}</strong>. Please use this ID for any future correspondence regarding this application. You can track the status of your application at any time by visiting your dashboard.
                    </p>
                    <p>
                        Our team will now review your submission in accordance with KASUPDA's regulations. You will be notified via your dashboard and registered email address of any updates or if further information is required.
                    </p>
                    <p className="font-semibold mt-8">
                        Sincerely,
                        <br />
                        The KASUPDA Team
                    </p>
                </div>
            </CardContent>
            <CardFooter className="p-0">
                <AcknowledgementActions />
            </CardFooter>
        </Card>
    );
}


export default function AcknowledgementPage({ params }: { params: { id: string } }) {
    return (
        <div className="container mx-auto px-2 sm:px-4 py-8 bg-gray-100 dark:bg-gray-900 print:bg-white">
             <Suspense fallback={<div className="text-center p-8">Loading Acknowledgement...</div>}>
                <AcknowledgementLetter id={params.id} />
            </Suspense>
        </div>
    );
}
